insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('lakshadweep-escape','Lakshadweep Escape','Island escape','Lakshadweep · Agatti Island','3 Nights · 4 Days','Ask for price','A relaxed Agatti-based island break with local sightseeing, lagoon time, boat experiences and snorkelling in Lakshadweep.','["Agatti Island", "Local island sightseeing", "Snorkelling", "Boat trip", "Dolphin watch", "Beach and lagoon time"]'::jsonb,'[{"day": "Day 1", "title": "Arrival & local sightseeing", "meals": "Lunch · Dinner", "description": "Arrive at Agatti Island Airport and transfer to the stay by AC vehicle. Check in, relax, enjoy lunch and explore the island. Sightseeing includes Kacheri Jetty, Lagoon Beach, Eastern Jetty and Andhan Beach. Dinner and overnight stay at Agatti Island."}, {"day": "Day 2", "title": "Agatti island exploration", "meals": "Lunch · Dinner", "description": "Continue the Agatti island experience with local sightseeing, relaxed island time and the surroundings around the stay. The supplied itinerary highlights local sightseeing for the day."}, {"day": "Day 3", "title": "Boat trip, snorkelling & dolphin watch", "meals": "Breakfast · Lunch · Dinner", "description": "After breakfast, enjoy a boat trip and snorkelling. Have lunch on the boat in the middle of the sea, then return to Agatti. Highlight of the day: dolphin watch and snorkelling. Overnight stay at Agatti Island."}, {"day": "Day 4", "title": "Departure", "meals": "Breakfast", "description": "Breakfast at the stay, check out and proceed to the airport for the flight back home with memories of Lakshadweep."}]'::jsonb,'["Accommodation / room stay", "Meals as shown in the day-wise itinerary", "Local island sightseeing", "Boat trip and snorkelling experience as scheduled", "Island visit support and local trip coordination"]'::jsonb,'["Flights to/from Lakshadweep unless specifically confirmed", "Personal expenses", "Activities or services not listed in the confirmed package", "Any extra charges caused by weather or operational changes"]'::jsonb,'["Final availability and price are subject to travel dates and confirmation.", "Activities may change due to weather, sea conditions or local operational restrictions.", "Exact inclusions will be confirmed before payment."]'::jsonb,NULL,'[]'::jsonb,0,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price=excluded.price,summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,sort_order=excluded.sort_order;
insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('delhi-manali-5n6d','Delhi + Manali','Group tour','Delhi · Manali · Solang · Kullu','5 Nights · 6 Days','₹10,000 / person','A Delhi and Manali group itinerary combining Delhi sightseeing, Manali local attractions, Solang / Rohtang route experiences and Kullu before the overnight return to Delhi.','["Jama Masjid", "Chandni Chowk", "Red Fort photo stop", "Hadimba Temple", "Solang Valley", "Atal Tunnel", "Kullu", "Volvo transfers"]'::jsonb,'[{"day": "Day 1", "title": "Arrival & Delhi sightseeing", "meals": "Meals / refreshments as arranged", "description": "Pickup at the railway station and Delhi sightseeing. Visit Jama Masjid, Chandni Chowk for local shopping and street food, and Red Fort for an exterior/photo stop. Return to the railway station and continue to Manali by Volvo."}, {"day": "Day 2", "title": "Manali local sightseeing", "meals": "Dinner", "description": "Arrival in Manali and transfer to the hotel. Early check-in is subject to availability. After freshening up, enjoy a half-day Manali local tour covering Hadimba Temple, Van Vihar Park and Tibetan Buddhist Monastery, followed by shopping at Mall Road. Dinner and stay at the hotel."}, {"day": "Day 3", "title": "Rohtang / Solang full-day tour", "meals": "Breakfast · Dinner", "description": "After breakfast, proceed for a full-day tour towards Rohtang Pass, with Atal Tunnel and Solang Valley en route. Optional adventure activities such as cable car, zipline, skiing, sledge, horse/yak ride and ATV bike are at own cost. Return to the hotel for dinner and overnight stay."}, {"day": "Day 4", "title": "Kullu & overnight Volvo", "meals": "Breakfast", "description": "After breakfast, check out. Visit Kullu for optional river rafting and paragliding, Kullu Vaishno Devi Temple, Kullu Shawl Factory and shopping. Evening drop at the Volvo pickup point and board the A/C semi-sleeper Volvo for the overnight journey to Delhi."}, {"day": "Day 5", "title": "Reach Delhi", "meals": "—", "description": "Reach Delhi by morning. The supplied quotation lists the overall duration as 5N/6D and provides day-wise details through Day 5."}]'::jsonb,'["2 nights accommodation at a 3-star hotel in Manali", "MAP meal basis: 2 breakfasts and 2 dinners", "1 day Delhi sightseeing", "3 days sightseeing at Manali", "Up and down Volvo travel"]'::jsonb,'["Train or flight fare", "Meals other than those mentioned in inclusions", "Personal expenses", "Entry fees for monuments, gondola, camera and adventure activities", "Room heater, snow dress, beverages, laundry, porter and tips", "River rafting, paragliding, snow activities and other adventure costs", "Extra 4x4 / snow vehicle charges during heavy snowfall", "Expenses caused by strikes, roadblocks, weather or natural calamities", "Services not mentioned in inclusions"]'::jsonb,'["Bookings are subject to availability and written confirmation.", "Rates can change based on travel dates, seasonality, hotel availability and transport price revisions.", "Cancellation charges apply as per the relevant hotel, transport provider or attraction policy.", "A 50% advance payment is required to block and confirm hotel accommodation and transportation services.", "No refund is provided for unused services due to no-show or late arrival."]'::jsonb,NULL,'[]'::jsonb,1,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price=excluded.price,summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,sort_order=excluded.sort_order;
