-- EzyGo Travel Supabase setup
create extension if not exists pgcrypto;

create table if not exists public.visa_groups (
  id text primary key, name text not null unique, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now()
);
create table if not exists public.visa_cards (
  id text primary key, group_name text not null, country text not null, flag text, type text, days integer not null default 0, validity text, fee text, date_label text, deadline text, description text, documents jsonb not null default '[]'::jsonb, cover_path text, detail_paths jsonb not null default '[]'::jsonb, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.packages (
  id text primary key, title text not null, tag text, destination text, duration text, price text, summary text, highlights jsonb not null default '[]'::jsonb, itinerary jsonb not null default '[]'::jsonb, inclusions jsonb not null default '[]'::jsonb, exclusions jsonb not null default '[]'::jsonb, terms jsonb not null default '[]'::jsonb, cover_path text, image_paths jsonb not null default '[]'::jsonb, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.feedback (
  id uuid primary key default gen_random_uuid(), name text, phone text, message text not null check (char_length(message) between 1 and 3000), created_at timestamptz not null default now()
);

alter table public.visa_groups enable row level security;
alter table public.visa_cards enable row level security;
alter table public.packages enable row level security;
alter table public.feedback enable row level security;

drop policy if exists "Public read visa groups" on public.visa_groups;
create policy "Public read visa groups" on public.visa_groups for select to anon, authenticated using (active = true);
drop policy if exists "Public read visa cards" on public.visa_cards;
create policy "Public read visa cards" on public.visa_cards for select to anon, authenticated using (active = true);
drop policy if exists "Public read packages" on public.packages;
create policy "Public read packages" on public.packages for select to anon, authenticated using (active = true);
drop policy if exists "Public submit feedback" on public.feedback;
create policy "Public submit feedback" on public.feedback for insert to anon, authenticated with check (char_length(message) between 1 and 3000);

